-- ============================================================================
--  Acto — 10 coachings importes depuis Google Drive (dossier IMPRO, 30/10/2026)
--  A passer dans l'editeur SQL Supabase (projet gssotstyevehbzydzhlq).
--  Re-executable : un coaching deja present sur le compte (meme titre) n'est
--  pas recree, et n'est jamais modifie.
-- ============================================================================
--
--  Chaque document du Drive devient un coaching sur TON COMPTE : dans le
--  Studio, Coaching -> Mes coachings -> « Sur mon compte » -> Recuperer.
--  Meme format que seed-2026-09-coachings-drive.sql (import du 17/09/2026).
--
--  NON importes, volontairement :
--   · les 5 coachings deja importes le 17/09 : inchanges sur le Drive depuis
--     (derniere modification le 16/09) — rien a mettre a jour ;
--   · « Coaching S6 du 07/10/2026 - Les QI cuits - Les effets speciaux et les
--     apartes » : le fichier est VIDE sur le Drive (0 octet) ;
--   · « Echauffement claps » : trois lignes de notes, pas un coaching ;
--   · « coaching juniors 4nov25 » : le brouillon d'ou viennent les deux
--     seances Juniors, importees sous leur forme redigee ;
--   · les deux « Copie de… » : identiques a leur original.
--
--  Durees : celles du document ; quand il n'en donne pas, le temps de la
--  seance est reparti a parts egales sur les blocs non chronometres.
--
--  Le compte est retrouve par e-mail. Laisser v_email vide ne marche que s'il
--  n'existe qu'un seul compte administrateur.
-- ============================================================================

do $seed$
declare
  v_email text := '';          -- <- ton e-mail de connexion Acto (ou vide : l'unique compte admin)
  v_owner uuid;
  v_admins int;
  v_ajouts int := 0;
begin
  if btrim(v_email) <> '' then
    select u.id into v_owner from auth.users u where lower(u.email) = lower(btrim(v_email));
    if v_owner is null then raise exception 'Aucun compte Acto avec l''e-mail %', v_email; end if;
  else
    select count(*) into v_admins from public.profiles where is_admin;
    if v_admins <> 1 then raise exception '% comptes admin : renseigne v_email en haut du fichier', v_admins; end if;
    select id into v_owner from public.profiles where is_admin;
  end if;

  insert into public.shared_resources (owner_id, resource_type, title, data, updated_by)
  select v_owner, 'entrainement', x.title, x.data, v_owner
    from (values
      -- 1. Coaching S3 du 21/09/2026 - Laugh - Les bases de l'improvisation (11 blocs) — source : Coaching S3 du 21/09/2026 - Laugh - Les bases de l'improvisation
      ('Coaching S3 du 21/09/2026 - Laugh - Les bases de l''improvisation', $json${"id":"988bfb4d-90ba-40ad-bc4b-73c4cb43bf8b","kind":"training","title":"Coaching S3 du 21/09/2026 - Laugh - Les bases de l'improvisation","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":4,"nbExercises":7},"targetSec":5100,"participants":[],"setlist":[{"id":"295ca215-ce81-4b48-be04-79bef58c1a62","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Cercle d'accueil — prénom, météo du jour, appréhensions","desc":"Cadre : lundi 21 septembre 2026, 17h20–18h45 (1h25) · La Condition Publique · Team Laugh (nom provisoire) · Encadrement : Antho (+ Seb + Kevin) · 9 jouteurs · Niveau débutant · Projet Laugh - Erasmus. Thème : les bases de l'improvisation — écoute, présence et coopération. En rond, chacun donne son prénom, sa météo du jour (son humeur) et, s'il le souhaite, ses appréhensions. Fil rouge : la séance progresse de l'écoute à deux (miroir, regard) vers l'écoute du groupe (comptage, classements, chaises), pour finir sur la présence individuelle face au groupe avec le « je suis là ». Objectifs de la séance : poser les fondamentaux (écoute, attention à l'autre, adaptation) ; comprendre le silence et sentir le groupe ; développer la coopération ; travailler la présence scénique ; créer un climat de confiance. Objectifs de l'exercice : prendre la température du groupe, nommer les peurs pour mieux les désamorcer, installer un climat bienveillant. Points de vigilance : revenir en fin de séance sur les appréhensions exprimées ici ; sur les exercices de groupe, repérer qui prend toute la place et qui s'efface ; garder un ton bienveillant et valorisant dans les débriefs.","duration_seconds":null,"wtype":"Accueil"}},{"id":"ccb73cdb-7295-43fb-8492-997c6aaa7d9d","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Échauffement du corps","desc":"Échauffement corporel collectif. Objectifs : mise en corps, préparer le physique aux exercices en mouvement.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"3738621e-47af-4422-b123-5fbfb5404e24","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"La douche","desc":"Chacun se « douche » pour rejeter les mauvaises ondes de la journée. Objectifs : laisser le quotidien à la porte, entrer disponible dans l'espace de jeu.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"c4c3195d-f2a2-454c-8ee0-027f5ae6ec5f","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Par deux — suivre les gestes","desc":"En binôme, on enchaîne des gestes le plus vite possible : clap, jambes, bras en l'air, à gauche ou à droite. Si les deux font le même geste, ils se tapent dans les mains. Objectifs : réactivité, attention au partenaire, montée d'énergie et premier rire partagé.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"b70a70ae-96f9-43a8-8986-acc91c99835a","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Par deux — le miroir","desc":"En binôme, jeu du miroir : l'un reproduit les mouvements de l'autre comme son reflet. Objectifs : savoir s'adapter à son environnement et à son partenaire, écoute corporelle, précision."}},{"id":"d566845f-a191-4878-b3ec-8792cdf54dde","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Gerodenomi","desc":"On regarde l'autre dans les yeux et on lui dit bonjour, en retenant les informations reçues. Objectifs : être attentif à l'autre et à l'information qu'il donne, mémorisation, soutenir le regard."}},{"id":"db792257-1d47-4b60-8423-256f70771d37","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Auto-comptage","desc":"On marche dans la salle et on compte de 1 jusqu'au nombre de participants, puis à rebours jusqu'à 1, sans ordre défini. Objectifs : sentir quand l'autre veut prendre la parole, apprendre à comprendre le silence, observer l'autre."}},{"id":"aaec6583-3e43-4b16-982e-4e511073c1ca","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Se ranger dans l'ordre","desc":"Le groupe se met en ligne dans l'ordre selon différents critères : taille, date de naissance, pointure, numéro de maison, vêtements du plus clair au plus foncé. Objectifs : parler à l'autre et en apprendre plus sur lui, se coordonner, partager les informations."}},{"id":"4cf7af14-f93a-4bbd-8afb-9d339e446e36","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Jeu des chaises","desc":"Le groupe doit trouver une stratégie en équipe pour réussir le jeu. [Règle à préciser] Objectifs : élaborer une stratégie collective, communiquer, garder son calme sous la pression."}},{"id":"fbfcb946-123e-419d-bb6c-89c1317ee4b1","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Killer","desc":"Un killer désigné en secret élimine les autres discrètement (par exemple d'un clin d'œil) ; le groupe doit le démasquer. [Règle à ajuster selon la version jouée] Objectifs : faire preuve d'observation, accepter la difficulté et l'élimination. Vigilance : l'élimination doit rester ludique et non frustrante."}},{"id":"b1f97fec-7f35-457d-bfdf-a5fe40f811e5","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"« Je suis là »","desc":"Chacun son tour, on passe devant les autres et on avance à un mètre d'eux. On regarde tout doucement chaque personne dans les yeux, une par une, en gardant son sérieux. Puis on revient en arrière et on dit bien fort : « Je suis là ». Objectifs : être présent, ne pas avoir peur de l'autre — on est tous différents, mais tous dans une même vie. Vigilance : laisser le temps à chacun, ne pas presser ceux qui ont du mal à soutenir le regard, accueillir les rires nerveux sans les sanctionner. Autres idées non réalisées : fusillade solo, balles de couleurs, une personne s'assied / une seule se lève."}}],"cursor":0,"journal":[],"matchDate":"2026-09-21"}$json$::jsonb),
      -- 2. Coaching S4 du 28/09/2026 - Laugh - Amener plus qu'un bonjour (4 blocs) — source : Coaching S4 du 28/09/2026 - Laugh - Amener plus qu'un bonjour
      ('Coaching S4 du 28/09/2026 - Laugh - Amener plus qu''un bonjour', $json${"id":"4f4f109d-ce7a-40c8-98be-bd25b4644c3b","kind":"training","title":"Coaching S4 du 28/09/2026 - Laugh - Amener plus qu'un bonjour","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":2,"nbExercises":2},"targetSec":6000,"participants":[{"name":"Kev","user_id":null},{"name":"Seb","user_id":null},{"name":"Louise","user_id":null},{"name":"Gab","user_id":null}],"setlist":[{"id":"3d22c945-2ae1-4997-843e-ddd8c9d32b37","type":"warmup","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : lundi 28 septembre 2026, environ 1h40 d'exercices · La Condition Publique · Team Laugh (nom provisoire) · Encadrement : Kevin, Seb · 4 jouteurs (Kev, Seb, Louise, Gab) · Niveau débutant · Projet Erasmus - Laugh · Adapté du coaching Les QI cuits — séance 3 du 16/09/2026. Thème : amener plus qu'un bonjour — contexte, émotion et relation dès la première réplique. Fil rouge : on garde le bonjour et la question, mais on les charge de contexte, d'émotion et de relation. La séance monte par paliers : l'échauffement travaille le personnage face au public, le cercle ajoute le contexte puis la relation, et le goalkeeper fait passer le tout en scène. Objectifs de la séance : amener du contexte, de l'émotion et une relation dès les premiers mots ; montrer que c'est le vide derrière un bonjour ou une question qui pose problème ; définir rapidement qui est l'autre ; gagner en détachement face au regard du public ; vérifier en débrief que ce qui est proposé est bien ce qui est reçu. Points de vigilance : repérer les bonjours et questions creuses et les faire reformuler sur-le-champ ; on ne bannit ni le bonjour ni la question, on ajoute ; attention à la surcharge inverse (trois informations dans une réplique enferment autant qu'une réplique vide) ; groupe de 4 : rotations rapides, surveiller la fatigue et prévoir une pause entre les deux blocs de 45 min.","duration_seconds":null,"wtype":"Accueil"}},{"id":"5169464f-9830-4b24-b2f4-9c7a0bb8a7a2","type":"warmup","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"warmup":{"name":"Le défilé de mode","desc":"En marchant dans l'espace, chacun prend une démarche et l'accentue, puis défile comme dans un défilé de mode. Progression conduite par le coach : 1) on est heureux, tout va bien ; 2) on voit que le public se moque de nous — on continue et on le vit bien ; 3) on continue, mais on est triste et on reste triste ; 4) on regarde le public qui devient peu à peu impressionné par ce qu'on fait. Objectifs : être de plus en plus détendu avec ce que peut penser le public, rester dans le personnage et l'attitude quelle que soit la réaction imaginée.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"a521e554-65c4-4ccc-8449-4b953967e337","type":"exercise","status":"planned","durationSec":2700,"locks":{},"recordedFiles":[],"exercise":{"name":"Cercle — le bonjour chargé","desc":"En cercle, on se dit bonjour en amenant un contexte et une émotion. Quatre paliers : 1) bonjour avec contexte et émotion ; 2) retour collectif sur le contexte amené et sur ce que les autres ont compris ; 3) on dit bonjour et on improvise à partir de là ; 4) même chose, mais chaque jouteur doit définir le plus rapidement possible qui est l'autre. Objectifs : cœur de la séance — un bonjour peut à lui seul poser une relation, un lieu et une humeur ; le palier 2 vérifie l'écart entre proposé et reçu ; le palier 4 pousse à offrir un rôle à l'autre plutôt qu'à attendre le sien."}},{"id":"351c243c-88a1-4c25-af93-3eead97761fa","type":"exercise","status":"planned","durationSec":2700,"locks":{},"recordedFiles":[],"exercise":{"name":"Goalkeeper — la question à contexte","desc":"Un jouteur reste en scène et reçoit à tour de rôle la question à contexte posée par un autre jouteur. Chaque passage donne lieu à une impro d'environ 3 minutes ; on tourne pour que chacun tienne le poste de goalkeeper. Objectifs : transformer la question en proposition — elle doit apporter de la matière au lieu d'en réclamer ; tenir une scène de 3 minutes à partir d'une seule réplique. Vigilance : 3 minutes est un format long, couper plus tôt si la scène a donné ce qu'elle avait à donner ; rester dans l'attitude même quand on ne sait plus où va la scène."}}],"cursor":0,"journal":[],"matchDate":"2026-09-28"}$json$::jsonb),
      -- 3. Coaching du 05/10/2026 - Laugh - Panique a bord (6 blocs) — source : Coaching_impro_Panique_a_bord.docx
      ('Coaching du 05/10/2026 - Laugh - Panique à bord', $json${"id":"fe285570-fcfd-4d6e-8de3-20512af21261","kind":"training","title":"Coaching du 05/10/2026 - Laugh - Panique à bord","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":2,"nbExercises":4},"targetSec":5700,"participants":[],"setlist":[{"id":"e5f7504f-eed3-4428-a527-0fbba6ae6b4b","type":"warmup","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : lundi 5 octobre 2026, environ 1h30 à 1h40 d'exercices · La Condition Publique · Team Laugh (nom provisoire) · Encadrement : Kevin · 6 jouteurs · Niveau débutant / intermédiaire · Projet Erasmus - Laugh · Dans la continuité du coaching « Amener plus qu'un bonjour ». Thème : panique à bord — construire une montée de tension et jouer la panique sans perdre le personnage. Fil rouge : ne pas simplement jouer « la panique », mais jouer quelqu'un qui essaie de gérer une situation paniquante. La séance monte progressivement : échauffement corporel, annonce de mauvaises nouvelles, montée de crise, puis impro longue. Objectifs de la séance : installer rapidement une situation de crise à partir d'une proposition simple ; faire ressentir la panique par le corps, la voix et le comportement, sans forcément crier ; faire monter la tension progressivement ; accepter et intégrer les propositions du partenaire ; ne pas chercher trop vite une solution ; garder un personnage cohérent dans le chaos. Points de vigilance : ne pas confondre panique et volume sonore ; si tout est au maximum dès le début, il n'y a plus d'évolution possible ; transformer les « qu'est-ce qu'on fait ? » en propositions jouables ; chaque nouvelle information doit pouvoir être utilisée ; l'objectif n'est pas la bonne solution mais de jouer les conséquences.","duration_seconds":null,"wtype":"Accueil"}},{"id":"1a9be622-fd1b-47e3-924f-94191cf3b1a8","type":"warmup","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"warmup":{"name":"La panique monte","desc":"Tout le monde se déplace dans l'espace ; le coach fait évoluer la situation : on est tranquillement sur un bateau, il fait beau ; quelque chose cloche, on remarque quelque chose d'étrange ; première alerte, on comprend qu'il y a un problème ; panique, le bateau est en train de couler ; panique avec contrainte — on est paniqué mais on doit rester poli, rassurer quelqu'un, nier le danger ou être persuadé d'avoir la solution. Objectif : faire comprendre la panique par l'attitude et le comportement, sans dépendre du cri.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"1c329ba7-f13d-414d-86fd-80ee7b919045","type":"exercise","status":"planned","durationSec":1500,"locks":{},"recordedFiles":[],"exercise":{"name":"Cercle — la mauvaise nouvelle","desc":"Un joueur avance vers un autre et lui annonce une mauvaise nouvelle ; la réplique doit contenir une information, une émotion et une relation. Tour 1 : uniquement la mauvaise nouvelle. Tour 2 : + l'émotion. Tour 3 : + la relation. Tour 4 : le partenaire définit immédiatement son personnage à partir de ce qui vient d'être proposé (« Capitaine, on a perdu le moteur ! » — « Je sais. C'est moi qui l'ai démonté. »). Objectif : chaque proposition doit créer du jeu et donner de la matière au partenaire."}},{"id":"ed83ccf8-c881-4a8e-9489-7e3013f1af0e","type":"exercise","status":"planned","durationSec":1200,"locks":{},"recordedFiles":[],"exercise":{"name":"Goalkeeper — les mauvaises nouvelles","desc":"Un joueur reste seul sur scène ; les autres viennent successivement lui donner de nouvelles informations, qu'il doit intégrer sans sortir de son personnage : « Capitaine, le moteur vient de lâcher. » — « Il n'y a plus de radio. » — « On vient de perdre le canot de sauvetage. » — « Il y a un requin. » — « Ce n'est pas un requin. C'est un sous-marin. » Consigne : ne pas chercher la bonne réponse, répondre à ce qui arrive et continuer à jouer."}},{"id":"f2d67322-527d-4732-ae93-1c1d2cd9d7c0","type":"exercise","status":"planned","durationSec":1500,"locks":{},"recordedFiles":[],"exercise":{"name":"Impro — « Panique à bord ! »","desc":"Deux joueurs sont à bord d'un bateau ; le coach donne une situation de départ (moteur en panne, bateau qui prend l'eau, tempête, personne tombée à la mer, plus de carburant…). La scène suit une montée en quatre temps : problème (quelque chose ne va pas) ; prise de conscience (c'est plus grave) ; désaccord (ils ne sont pas d'accord sur la réaction) ; panique et conséquence (la situation devient incontrôlable et une décision produit un nouvel événement)."}},{"id":"bb2a6def-7cd7-4acb-83c7-0a8b4ccab899","type":"exercise","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"exercise":{"name":"Débrief final","desc":"Qu'est-ce qui rendait votre personnage paniqué ? Avez-vous utilisé ce que votre partenaire vous donnait ? À quel moment la scène est-elle vraiment devenue intéressante ? Fallait-il forcément crier pour montrer la panique ? Qu'est-ce qui était le plus drôle : la panique elle-même ou la manière dont les personnages réagissaient ? Fil rouge : ne pas jouer la panique ; jouer quelqu'un qui essaie de gérer une situation paniquante."}}],"cursor":0,"journal":[],"matchDate":"2026-10-05"}$json$::jsonb),
      -- 4. Coaching S4 du 23/09/2026 - Les QI cuits - Manipulation / lieu / personnage (10 blocs) — source : Coaching S4 du 23/09/2026 - Les QI cuits - Manipulation / lieu / personnage
      ('Coaching S4 du 23/09/2026 - Les QI cuits - Manipulation / lieu / personnage', $json${"id":"c13183e3-54bc-4d0b-96a9-e85ce5cfb677","kind":"training","title":"Coaching S4 du 23/09/2026 - Les QI cuits - Manipulation / lieu / personnage","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":3,"nbExercises":7},"targetSec":7200,"participants":[{"name":"Vero","user_id":null},{"name":"Kevin","user_id":null},{"name":"Kev VDB","user_id":null},{"name":"Ben","user_id":null},{"name":"Seb","user_id":null},{"name":"David","user_id":null},{"name":"Sophie","user_id":null},{"name":"Lucie","user_id":null}],"setlist":[{"id":"7ac85cd3-824d-4a1e-ac81-c96d6e197bab","type":"warmup","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : 23/09/2026, 19h–21h · La Prairie · Team Les QI cuits · 1 coach — Jonathan · 9 jouteurs (Vero, Kevin, Kev VDB, Ben, Seb, David, Sophie, Lucie, … [à compléter]) · Niveau débutant. Thème : manipulation, création de lieu et personnage. Fil rouge : tout part de la manipulation d'objets et de la lisibilité du jeu — objet seul, puis personnage, précision du geste, lieu construit collectivement et enfin confrontation de deux propositions. Principe à chaque étape : en impro, on ne montre pas, on fait comprendre. Objectifs de la séance : rendre la manipulation lisible pour le public et le partenaire ; construire un personnage à partir du corps (point moteur) et le faire varier avec l'échelle de vitesse 1 à 10 ; respecter le décor installé par l'autre ; développer l'adaptabilité ; réinvestir le tout en mixtes 1 contre 1. Points de vigilance : repérer les manipulations approximatives (objet qui change de taille, porte qui se déplace, comptoir oublié) ; vérifier que les jouteurs explorent aussi les vitesses basses ; groupe de 9 : prévoir la rotation à l'avance sur les exercices de lieu, de mime miroir et de confrontation ; débriefs courts et concrets.","duration_seconds":null,"wtype":"Accueil"}},{"id":"3624b548-30a1-4d29-af19-43d4d2a79e23","type":"warmup","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"warmup":{"name":"Échauffement — le frottement","desc":"On se frotte de la tête aux pieds pour se réveiller et se débarrasser de la journée. Objectifs : mise en corps, entrée collective dans l'espace de jeu.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"df4b6586-eed8-490f-a3ba-8bd46eda79d3","type":"warmup","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"warmup":{"name":"Cercle — l'objet mimé qui circule","desc":"En cercle, chacun fait un mime d'utilisation d'un objet puis le passe à son voisin, qui en fait à son tour ce qu'il veut. Objectifs : premières manipulations, détournement d'objet, clarté du geste.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"24e6d445-1f3a-4c3b-bd36-0a6139cacb60","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Cercle — le groupe suit en décalé","desc":"Même principe, mais le groupe reprend la manipulation du jouteur avec un léger temps de retard, dès qu'il a compris ce que celui-ci faisait ; le jouteur finit par donner l'objet à son voisin. Objectifs : vérifier en direct si le geste est lisible — si le groupe ne suit pas, la manipulation n'est pas claire ; écoute et observation. Vigilance : si le groupe ne suit pas, le renvoyer au jouteur sans le vivre comme un échec."}},{"id":"fcebd356-c798-4f72-8cc9-18d334aaf1f2","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Point moteur et personnage","desc":"Déplacement dans l'espace en changeant de point moteur, et improvisation d'un personnage dès qu'on le sent venir. Le coach demande à tour de rôle l'émotion du personnage, puis qui il est ; les jouteurs répondent en restant ce personnage. Une échelle de vitesse de 1 à 10 module les personnages tout du long. Objectifs : faire naître le personnage du corps plutôt que de l'idée, explorer une large palette en jouant sur l'intensité."}},{"id":"fe9729b6-9e0c-4566-8b72-2838ed8ecb1c","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Entraînement à la manipulation","desc":"Comment ouvre-t-on une porte ? Comment tient-on un objet ? On le fait d'abord avec de vrais objets, puis on le mime. Principe : en impro, on ne montre pas, on fait comprendre visuellement où on est et ce qu'on fait, pour le public et pour l'autre jouteur. Objectifs : précision et réalisme du geste, mémoire corporelle de l'objet réel, lisibilité."}},{"id":"3043b1fa-3d96-41cf-83d8-f6b04daa44d5","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Agrémenter le lieu sans le détruire","desc":"Un premier jouteur installe une pièce ou un lieu ; les autres montent à tour de rôle pour l'agrémenter, sans détruire le décor déjà installé : on ne passe pas à travers une porte ou un comptoir, sinon le lieu et la lisibilité de l'impro s'effondrent. Objectifs : mémoire collective du décor, cohérence spatiale, construire avec l'autre plutôt qu'à côté de lui."}},{"id":"4e9c9fd7-431e-4d8a-be4d-b712772c261c","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Mime miroir","desc":"Deux jouteurs en scène : l'un mime un décor, une scène, l'autre doit l'imiter. Les jouteurs restés dehors doivent deviner le lieu et l'action. Objectifs : le regard extérieur valide la lisibilité, synchronisation à deux, précision partagée."}},{"id":"78c6d68e-80a1-460f-80a3-4eee17ddf631","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Confrontation de manipulations","desc":"Deux jouteurs dos à dos miment chacun une action de leur côté, puis tournent de 90 degrés et commencent à improviser ensemble ; leur jeu doit englober les deux lieux et les deux manipulations. Objectifs : adaptabilité, acceptation de la proposition de l'autre, justification de deux univers en un seul."}},{"id":"7c62ec8a-e97f-4ef0-8810-ba697687e103","type":"exercise","status":"planned","durationSec":720,"locks":{},"recordedFiles":[],"exercise":{"name":"Entraînement match — mixtes 1 contre 1","desc":"3 impros mixtes, catégorie libre, 1 contre 1, de 3 minutes, avec services autorisés. Objectifs : réinvestir la manipulation et le personnage en conditions de match, tenir une scène à deux sur la durée. Vigilance : le décor planté reste-t-il vivant jusqu'à la fin ou est-il oublié après trente secondes ?"}}],"cursor":0,"journal":[],"matchDate":"2026-09-23"}$json$::jsonb),
      -- 5. Coaching S5 du 30/09/2026 - Les QI cuits - Manipulation lieu personnage approfondissement (6 blocs) — source : Coaching S5 du 30/09/2026 - Les QI cuits - Manipulation lieu personnage approfondissement
      ('Coaching S5 du 30/09/2026 - Les QI cuits - Manipulation lieu personnage approfondissement', $json${"id":"4675fd39-3720-4e4c-b35f-412d0df03232","kind":"training","title":"Coaching S5 du 30/09/2026 - Les QI cuits - Manipulation lieu personnage approfondissement","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":2,"nbExercises":4},"targetSec":5400,"participants":[{"name":"Vero","user_id":null},{"name":"Vero","user_id":null},{"name":"David","user_id":null},{"name":"Gaston","user_id":null},{"name":"Quentin","user_id":null},{"name":"Ben","user_id":null},{"name":"Seb","user_id":null},{"name":"Sophie","user_id":null},{"name":"Lucie","user_id":null},{"name":"Fabienne","user_id":null}],"setlist":[{"id":"62131059-5ca1-4940-a29f-d7c424aafef0","type":"warmup","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : mercredi 30 septembre 2026, 19h00–20h30 (1h30) · La Prairie · Team Les QI cuits · 1 coach — Jonathan · 10 jouteurs (Vero, Vero, David, Gaston, Quentin, Ben, Seb, Sophie, Lucie, Fabienne) · Niveau débutant. Thème : manipulation, création de lieu et personnage — approfondissement. Fil rouge : la séance 4 a posé la manipulation ; celle-ci l'approfondit et la met à l'épreuve de la transmission — ce que je fais doit être assez clair pour que l'autre le reprenne ou le devine. Les deux derniers exercices transposent cette exigence sur le personnage. Objectifs de la séance : une manipulation réussie est une manipulation que l'autre peut reprendre à l'identique ; faire comprendre sans nommer ; incarner un personnage par le corps (animal, point moteur, démarche, émotion) et tenir cette attitude en parlant ; passer progressivement du collectif au solo devant le groupe. Points de vigilance : 10 jouteurs en 1h30 — chronométrer les solos et garder les débriefs très courts ; faire le lien explicite avec la séance 4 : la lisibilité reste le critère de réussite, sur l'objet comme sur le personnage.","duration_seconds":null,"wtype":"Accueil"}},{"id":"73b9e1dc-06da-4fe3-89d8-a7e5cc0c110e","type":"warmup","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"warmup":{"name":"Le tour des manipulations","desc":"En cercle, chaque jouteur mime une manipulation. À chaque top du coach, chacun reprend la manipulation de son voisin de gauche ; on enchaîne jusqu'à retrouver la manipulation de départ. Objectifs : observation, mémoire du geste, test direct de lisibilité — si la manipulation se déforme au fil du tour, elle n'était pas claire au départ. Vigilance : un cercle de 10 fait dix tops avant de retrouver sa manipulation, annoncer la règle clairement et garder un rythme soutenu.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"eb765487-59e8-4194-8c0f-f21aa449b3a4","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"La manipulation reprise par tout le groupe","desc":"En cercle, un jouteur commence une manipulation et tout le monde l'imite ; puis le jouteur suivant en propose une nouvelle. Objectifs : précision partagée, synchronisation du groupe, oser proposer devant les autres."}},{"id":"36892cf2-dba9-4411-8124-6dd94c09ecd1","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Je suis un objet","desc":"Chacun son tour, on fait une improvisation où l'on est un objet. L'improvisateur ne dit pas ce qu'il est : il décrit ce qu'il fait. En fin d'impro, on demande aux autres quel était l'objet. Objectifs : faire comprendre par l'action et non par l'étiquette, tenir un solo court, vérifier l'écart entre joué et reçu. Vigilance : guetter ceux qui nomment l'objet sans s'en rendre compte, ou qui le dessinent au lieu de le vivre."}},{"id":"4340f4ed-f517-4118-961d-29e684d16ec5","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"L'attitude animale","desc":"On marche dans l'espace en prenant une attitude inspirée par un animal ; le coach demande ensuite à chacun qui il est, et il répond en gardant cette attitude. Objectifs : incarner plutôt qu'imiter — une qualité de présence, pas un numéro d'animal ; tenir le corps du personnage tout en parlant. Vigilance : le jouteur reste un humain traversé par l'animal."}},{"id":"a3d508ce-3403-493a-b081-0c0b9229c20b","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Le personnage et la chaise","desc":"Les jouteurs marchent dans l'espace avec l'attitude d'un personnage construite à partir des émotions, du point moteur ou de la démarche, autour d'une chaise. À tour de rôle, chacun monte et improvise : qui il est, ce qu'il fait, ce qu'il vit et comment il le vit. Objectifs : assembler tout le travail en un personnage complet, tenir seul en scène, faire exister une vie intérieure. Vigilance : avec 10 jouteurs c'est le plus gros bloc, veiller à ce que chacun passe."}}],"cursor":0,"journal":[],"matchDate":"2026-09-30"}$json$::jsonb),
      -- 6. Coaching S7 du 14/10/2026 - Les QI cuits - Les effets speciaux (suite) (8 blocs) — source : Coaching S7 du 14/10/2026 - Les QI cuits - Les effets speciaux (suite).docx
      ('Coaching S7 du 14/10/2026 - Les QI cuits - Les effets speciaux (suite)', $json${"id":"bd42d5f1-625e-45da-a072-953e1c012c76","kind":"training","title":"Coaching S7 du 14/10/2026 - Les QI cuits - Les effets speciaux (suite)","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":2,"nbExercises":6},"targetSec":7200,"participants":[],"setlist":[{"id":"5e5cfbbd-2548-478f-a26f-6d94323eb64d","type":"warmup","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : mercredi 14 octobre 2026, 19h00–21h00 (2h00) · La Prairie · Team Les QI cuits · 1 coach — Sam · 11 jouteurs · Niveau débutant. Thème : les effets spéciaux (suite) — niveaux, échelles et points de vue. Fil rouge : après les effets spéciaux collectifs de la séance 6, on travaille l'effet de perspective : relier deux propositions séparées, construire une chaîne où chacun hérite de l'autre, installer deux échelles sur un même plateau, remettre en jeu en impro, finir sur une forme chorale. Principe : le public comprend où je suis par ce que mon corps montre, pas par ce que j'annonce. Objectifs de la séance : passer de l'effet collectif à l'effet de perspective ; jouer ensemble sans être au même endroit ni à la même échelle ; installer les niveaux de jeu comme outil de scène ; faire comprendre un personnage non humain par la réaction ; continuer à travailler l'acceptation. Points de vigilance : le niveau doit se voir, pas s'annoncer ; 11 jouteurs en 2h — les impros 1 contre 1 sont le gros du temps de passage, prévoir la rotation et garder les débriefs courts ; réserver au moins 40 minutes au catch, quitte à raccourcir l'immeuble.","duration_seconds":null,"wtype":"Accueil"}},{"id":"308f275d-d165-4432-8c95-8bb4959bb6d9","type":"warmup","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"warmup":{"name":"Dos à dos — deux manips qui se rencontrent","desc":"Deux jouteurs dos à dos font chacun une manipulation de leur côté, sans voir celle de l'autre ; dès qu'ils sont prêts, ils se retournent et improvisent ensemble. Objectifs : acceptation et adaptabilité — chacun arrive avec son univers et doit faire tenir les deux dans une même scène. Reprise de l'exercice de la séance 4, en ouverture.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"e090c8a7-d979-4d9b-b0d0-3056e0c4b8a9","type":"exercise","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"exercise":{"name":"L'arbre, la pomme et le ver de terre","desc":"Un jouteur s'avance en arbre : « Je suis un arbre et je profite du soleil ». Un deuxième : « Je suis une pomme et je vis dans mon arbre ». Un troisième choisit lequel des deux il garde : « Je suis un ver de terre et je vis dans la pomme » ; le non-retenu va s'asseoir, et ainsi de suite. À un moment, le coach annonce : « On va essayer de retourner à l'arbre ». Objectifs : rapidité de proposition, acceptation, conscience de l'échelle ; la remontée vers l'arbre ajoute un objectif commun. Vigilance : tenir la cadence sans chercher la trouvaille, bien faire asseoir le jouteur non retenu ; sur la remontée, c'est l'intention commune qui compte."}},{"id":"49df536c-b986-4e1a-8c4c-a5f8fe00d5a0","type":"exercise","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"exercise":{"name":"Pairs et impairs — l'avion et les géants","desc":"Les jouteurs se déplacent puis se séparent en pairs et impairs. « Les pairs, vous êtes dans un avion et vous regardez en bas des petites personnes. » — « Les impairs, vous êtes les petits personnages et vous faites coucou à l'avion. » Puis : « Les impairs, vous êtes des géants gigantesques ; les pairs, des nains minuscules. » Objectifs : être à des niveaux et des endroits différents et jouer ensemble malgré tout ; l'inversion des tailles empêche de s'installer dans le confort d'une seule échelle."}},{"id":"baf87891-ac53-4d3f-8bca-080afd4d55bb","type":"exercise","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"exercise":{"name":"Impro 1 contre 1 — pas au même niveau","desc":"Improvisations à deux où les jouteurs montrent qu'ils ne sont pas au même niveau : un en haut et un en bas, un dedans et un dehors, deux étages, deux altitudes. Objectifs : réinvestir l'exercice précédent en jeu — le niveau se voit dans le corps (regard, adresse, hauteur de voix) avant d'être dit."}},{"id":"b1f3838b-a829-44aa-9483-1e0d0243da54","type":"exercise","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"exercise":{"name":"Impro 1 contre 1 — le ver de terre et le pêcheur","desc":"Improvisations à deux sur un rapport d'échelle marqué : l'un est par exemple un ver de terre, l'autre un pêcheur. Le ver de terre fait comprendre ce qu'il est par ses réactions aux actions du pêcheur qui le manipule. Objectifs : jouer un non-humain sans l'annoncer — c'est la réaction au traitement subi qui le rend lisible ; pour le pêcheur, manipuler avec assez de précision pour donner de quoi réagir. Vigilance : le ver réagit, il n'illustre pas."}},{"id":"3334e747-0989-4c67-bc40-7e7b467b6694","type":"exercise","status":"planned","durationSec":660,"locks":{},"recordedFiles":[],"exercise":{"name":"Les étages d'un immeuble","desc":"Les jouteurs sont en ligne ; chacun s'avance à son tour pour raconter la vie de l'immeuble et les interactions entre habitants. Objectifs : forme chorale qui rassemble la séance — chaque étage est un niveau, la vie naît de ce que les habitants se font sans se croiser ; écoute et mémoire collective. Vigilance : les habitants se répondent d'un étage à l'autre plutôt que d'empiler des portraits indépendants."}},{"id":"03aaf4aa-9718-410d-8046-79794d71b344","type":"exercise","status":"planned","durationSec":2400,"locks":{},"recordedFiles":[],"exercise":{"name":"Catch d'impro — 3 équipes (4 / 4 / 3)","desc":"Trois équipes de 4, 4 et 3 jouteurs, une catégorie par confrontation. A contre B — abécédaire : chaque réplique commence par la lettre suivante (lettre de départ tirée au sort). B contre C — contact : on ne parle qu'en contact physique avec un partenaire. C contre A — carré des émotions : le plateau est divisé en quatre zones portant chacune une émotion, on change d'émotion en changeant de zone. Durée et désignation du vainqueur au choix du coach (vote du public, des jouteurs au repos, ou les deux). Objectifs : finir en conditions réelles avec trois contraintes de nature différente. Vigilance : l'abécédaire ne dispense pas de jouer ; sur le carré, se déplacer vraiment d'une zone à l'autre ; l'équipe de 3 joue en infériorité, prévoir qui se met au repos ou assumer le déséquilibre."}}],"cursor":0,"journal":[],"matchDate":"2026-10-14"}$json$::jsonb),
      -- 7. Coaching CM2 - Seance 1 - Decouverte de l'improvisation (10 blocs) — source : Coaching CM2 - Seance 1 - Decouverte de l'improvisation.docx
      ('Coaching CM2 - Séance 1 - Découverte de l''improvisation', $json${"id":"ef6ac205-e2ed-4349-a41b-1129570d3da7","kind":"training","title":"Coaching CM2 - Séance 1 - Découverte de l'improvisation","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":5,"nbExercises":5},"targetSec":4980,"participants":[],"setlist":[{"id":"ffb2e737-329a-401e-828b-ced544a56c0b","type":"warmup","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et règles du jeu","desc":"Cadre : date, horaire, lieu et encadrement à compléter · 1h de déroulé (variante ci-dessous) · 10 enfants de CM2 (10 à 11 ans), grands débutants · Prévoir un espace dégagé pour marcher et se coucher au sol · Matériel : un stylo ou un objet quelconque. Thème : découverte de l'improvisation — oser, écouter, accepter. En cercle, trois règles seulement, annoncées en une minute : ici, on ne peut pas se tromper, il n'y a pas de bonne réponse ; on rit avec, jamais de — celui qui est au milieu prend un risque pour tout le monde ; quand le coach tape deux fois dans les mains, tout le monde s'arrête. Fil rouge : tout le monde joue tout le temps ; on va du cercle, où l'on est protégé par le groupe, jusqu'à la scène à deux, par étapes assez petites pour qu'aucun enfant ne se rende compte qu'il improvise. Objectifs de la séance : apprendre les prénoms et faire exister le groupe ; lever la peur du ridicule ; installer l'acceptation ; découvrir le mime et la manipulation ; terminer par un premier vrai passage en scène. Variante en 1 heure : supprimer « Ceci n'est pas un stylo » et « Les lettres de l'alphabet », réduire l'impro finale à trois passages — ne jamais sacrifier la première impro. Points de vigilance : montrer plutôt qu'expliquer (une consigne de plus de trois phrases est perdue) ; aucun exercice d'élimination ; poser la règle du rire dès le début et y revenir à la première moquerie ; ne rien corriger techniquement aujourd'hui ; repérer ceux qui n'osent pas (en binôme avec un moteur) et celui qui prend toute la place ; tout prend un tiers de temps en plus que prévu.","duration_seconds":null,"wtype":"Accueil"}},{"id":"6c5dea05-acfd-4465-8748-3527b0162abd","type":"warmup","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"warmup":{"name":"Le cercle des prénoms","desc":"En cercle, chacun dit son prénom en y ajoutant un geste ; tout le groupe répond « Bonjour [prénom] ! » en refaisant le geste avec la même énergie. Deuxième tour : plus vite, et on ajoute une émotion au geste. Objectifs : mémoriser les prénoms et faire faire à chacun son premier passage, immédiatement imité par les autres, donc sans risque. (Repris du coaching Laugh du 14/09.)","duration_seconds":null,"wtype":"Échauffement"}},{"id":"da8cec7c-acc7-4296-82aa-be1a8c00b694","type":"warmup","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"warmup":{"name":"La douche","desc":"Chacun se « douche » de la tête aux pieds pour faire tomber la journée d'école, puis secoue bras, jambes et tête pour tout évacuer. Objectifs : mise en corps et sas entre l'école et l'atelier — des CM2 qui arrivent de classe ont besoin de bouger avant d'écouter. (Repris du coaching Laugh du 21/09.)","duration_seconds":null,"wtype":"Échauffement"}},{"id":"65ed7fdb-27f5-4b74-aedb-48a7f447cdae","type":"warmup","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"warmup":{"name":"Le clap","desc":"En cercle, on se passe un clap ; celui qui le reçoit le redonne à quelqu'un d'autre ou le renvoie à l'envoyeur. On accélère. Puis les effets spéciaux : celui qui reçoit le clap peut l'arrêter et lancer une action — « Samba ! » et tout le monde danse, « Balançoire ! » et tout le monde se balance — puis ça repart. Objectifs : réactivité, énergie, et première leçon d'acceptation : quand quelqu'un lance « Samba », personne ne discute. (Repris du coaching QI cuits du 10/10.)","duration_seconds":null,"wtype":"Échauffement"}},{"id":"4ec7a590-1e06-44a9-8e88-ec2a497e6b42","type":"warmup","status":"planned","durationSec":420,"locks":{},"recordedFiles":[],"warmup":{"name":"Les actions synchronisées","desc":"Les enfants marchent dans l'espace. Au signal : 1 clap, on saute tous ensemble ; 2 claps, on s'accroupit ; 3 claps, on tourne sur soi-même ; 4 claps, on s'arrête, on compte 1, 2, 3 à voix haute et on repart ensemble. Objectifs : écoute du signal et plaisir de faire ensemble ; installe aussi le signal d'arrêt pour toute l'année. (Repris du coaching QI cuits du 09/09.)","duration_seconds":null,"wtype":"Échauffement"}},{"id":"8e997482-8ecc-4008-9e18-9e72ba2ffeb9","type":"exercise","status":"planned","durationSec":480,"locks":{},"recordedFiles":[],"exercise":{"name":"Ceci n'est pas un stylo","desc":"En cercle, on se passe un stylo ; chacun annonce « Ceci n'est pas un stylo, c'est… » et mime ce que c'est — une brosse à dents, un téléphone, une épée, un hamster — puis le passe à son voisin. Objectifs : détournement d'objet et premier mime ; tout le monde a une idée en vingt secondes et le cercle protège encore. (Repris du coaching QI cuits du 16/09, « Ceci n'est pas ma main ».)"}},{"id":"ac85a806-daeb-44f6-9508-09abad23ae64","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Les lettres de l'alphabet","desc":"Par groupes de deux ou trois, les enfants forment avec leur corps la lettre annoncée par le coach (pour le X, l'un se couche en travers de l'autre ; pour le P, l'un reste debout pendant que l'autre fait la boucle). Après chaque lettre, les groupes se regardent : reconnaît-on la lettre ? Pour finir, tout le groupe forme un mot court de quatre ou cinq lettres. Objectifs : coopération, contact physique dans un cadre clair, première idée de lisibilité ; tout le monde joue en même temps. (Repris du coaching « Faire comprendre sans parler ».)"}},{"id":"b904f462-259b-4c65-92bb-ec39fadffa0d","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Mais qu'est-ce que tu fais ?","desc":"En cercle, le premier s'avance et mime une action (se brosser les dents). Son voisin s'avance et demande : « Mais qu'est-ce que tu fais ? » Le premier annonce tout autre chose (« je tonds la pelouse ! ») et retourne à sa place ; le deuxième se met à tondre la pelouse jusqu'à ce que le suivant lui pose la même question. Objectifs : accepter sans discuter l'action reçue, continuer à mimer tout en pensant à autre chose ; l'absurde des réponses fait le reste. (Repris du coaching « Faire comprendre sans parler ».)"}},{"id":"e2ace6d1-793e-4215-987b-8d28aa7cd937","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Première impro — 30 secondes à deux","desc":"Improvisations libres à deux, 30 secondes chronométrées, avec un titre simple et concret : « la récré », « le dentiste », « la cantine », « le chien perdu ». Cinq passages suffisent pour que les dix enfants passent. Après chaque passage, une seule phrase du coach, positive. Objectifs : premier passage en scène en conditions réelles — trop court pour échouer, trop court pour avoir peur. (Repris du coaching de découverte avec les grands débutants.)"}},{"id":"0163ce98-bf56-4a4b-aa38-6f8118deda49","type":"exercise","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"exercise":{"name":"Rite de fin","desc":"En cercle, chacun dit un mot sur la séance — un seul, pas une phrase. Puis le groupe fait monter un applaudissement du plus doux au plus fort, et on s'arrête net. Objectifs : refermer la séance par un rituel reconnaissable qui reviendra à chaque fois ; avec des enfants, c'est lui qui donne envie de revenir. En réserve si un exercice tombe à plat : l'échange de prénoms, se ranger dans l'ordre, le miroir à deux."}}],"cursor":0,"journal":[],"matchDate":""}$json$::jsonb),
      -- 8. Coaching - Nouveau groupe - Faire comprendre sans parler (6 blocs) — source : Coaching - Nouveau groupe - Faire comprendre sans parler.docx
      ('Coaching - Nouveau groupe - Faire comprendre sans parler', $json${"id":"2cbd8135-f24b-4167-a275-8a24e4080f93","kind":"training","title":"Coaching - Nouveau groupe - Faire comprendre sans parler","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":3,"nbExercises":3},"targetSec":4200,"participants":[],"setlist":[{"id":"a4440800-6f0d-4120-a6cd-c79d34bcd53d","type":"warmup","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"warmup":{"name":"Accueil et cadrage","desc":"Cadre : séance n° 1 [à confirmer] · date, horaire, lieu, nom du groupe, encadrement et niveau à compléter · une quinzaine de jouteurs [à confirmer] · Matériel : languettes de lieux préparées à l'avance (exercice « planter un lieu en silence »). Thème : faire comprendre sans parler — mime, manipulation et lecture de l'autre. Fil rouge : le corps parle avant la bouche. Les deux échauffements mettent le groupe en contact et en énergie et posent la question qui traverse la séance — est-ce lisible de l'extérieur ? On installe ensuite la mécanique centrale (mimer une chose, en dire une autre), on la met en scène dans une forme continue, puis on isole la manipulation pure avec le lieu planté en silence. Principe à rappeler : on ne montre pas, on fait comprendre. Objectifs de la séance : mettre le groupe en contact et en énergie ; construire une image collective lisible ; dissocier le dire et le faire ; lire la proposition de l'autre et la rejoindre au bon moment ; rendre la manipulation lisible sans un mot. Points de vigilance : le reste du public travaille aussi — c'est lui qui juge du moment où le lieu ou l'action sont lisibles, le dire explicitement ; groupe d'une quinzaine : les deux derniers exercices ne font passer que deux jouteurs à la fois.","duration_seconds":null,"wtype":"Accueil"}},{"id":"d36ac734-101d-4863-ae8f-93f51fda3cf4","type":"warmup","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"warmup":{"name":"Les lettres de l'alphabet","desc":"Par petits groupes de deux ou trois, les jouteurs forment avec leur seul corps la lettre donnée par le coach (pour le X, une personne se couche en travers d'une autre ; pour le P, l'une reste debout pendant que l'autre fait la boucle). Objectifs : contact physique et coopération rapide, première leçon de lisibilité — la forme doit se lire de l'extérieur. Vigilance : faire regarder les autres groupes, la lettre est-elle lisible ?","duration_seconds":null,"wtype":"Échauffement"}},{"id":"a6166c36-29a0-4576-8d8f-e61de202b130","type":"warmup","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"warmup":{"name":"Cardio et association de mots","desc":"En rond, une personne trottine vers quelqu'un et lui dit un mot (« église ») ; celui qui le reçoit prend la place libre puis court vers une nouvelle personne avec un mot associé (« prière »). Le coach met en circulation un deuxième puis un troisième mot ; chacun lève les bras pour signaler qu'il est disponible. Objectifs : mise en énergie, association d'idées sans réfléchir, vigilance périphérique. Vigilance : n'ajouter un mot que si le précédent circule bien.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"81fbc916-a7d2-4416-a6de-23a71c3811d2","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"« Mais qu'est-ce que tu fais ? » en cercle","desc":"En rond, le premier s'avance et commence une manipulation (se brosser les dents). Son voisin de droite l'observe et demande : « Mais qu'est-ce que tu fais ? » Le premier annonce une action sans rapport (« je tonds la pelouse ») et retourne à sa place ; le deuxième se met à tondre la pelouse, et ainsi de suite. Objectifs : dissocier le dire et le faire, mimer précisément en pensant à autre chose, accepter sans négocier l'action reçue. Vigilance : ceux qui lâchent leur mime au moment de répondre, ou annoncent une action trop proche."}},{"id":"6546d24e-561c-451f-86c0-b6f4bcf837a5","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Le complément d'action","desc":"Même enchaînement, en scène et à deux : un jouteur commence une manipulation silencieuse (un lieu, une action). Dès qu'un spectateur comprend, il vient compléter de façon cohérente (le premier nettoie les vitres, le second fait les poussières) et une courte impro parlée démarre (1 min 30 à 2 min). Au moment qu'il choisit, le second demande : « Mais qu'est-ce que tu fais ? » ; le premier répond une action totalement différente (« je répare mon vélo ») et quitte la scène ; le second se met à réparer un vélo jusqu'à ce qu'un nouveau spectateur le rejoigne. Objectifs : lire l'action de l'autre et y entrer sans la détruire, basculer d'un univers à l'autre sans temps mort. Vigilance : le second ne monte ni trop tôt ni trop tard, et ne pose pas la question trop vite."}},{"id":"78b9d43a-2cfd-4190-a693-8e6fd1a4253a","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Planter un lieu en silence","desc":"Le coach a préparé des languettes portant des lieux précis (une chambre d'hôtel…). Un jouteur lit son étiquette et installe le lieu sans parler ; dès que le lieu est clair pour le public, un deuxième jouteur le rejoint, avec l'autorisation des services. Objectifs : précision de la manipulation et choix des bons objets — un lieu se plante par deux ou trois gestes justes, pas par un inventaire ; savoir quand le lieu est assez posé pour y entrer. Vigilance : deux ou trois objets bien manipulés valent mieux qu'un décor complet et flou."}}],"cursor":0,"journal":[],"matchDate":""}$json$::jsonb),
      -- 9. Coaching Juniors - Seance 1 - Decouverte du groupe et premieres emotions (8 blocs) — source : Coaching Juniors - Seance 1 - Decouverte du groupe et premieres emotions.docx
      ('Coaching Juniors - Séance 1 - Découverte du groupe et premières émotions', $json${"id":"7d213b48-e3f7-48bb-ba81-448d09aee703","kind":"training","title":"Coaching Juniors - Séance 1 - Découverte du groupe et premières émotions","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":3,"nbExercises":5},"targetSec":7200,"participants":[],"setlist":[{"id":"0f9fba91-52e1-4705-a79b-00f8c970e4db","type":"warmup","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"warmup":{"name":"Introduction — prénoms et scoop","desc":"Cadre : 4 novembre [année à confirmer : 2024 dans le document source, 2025 dans le nom du fichier] · 19h00–21h00 (2h00) · Team Juniors [nom à compléter] · Encadrement : Naya · groupe, lieu et niveau à compléter · Matériel : aucun. Thème : découverte du groupe et début du travail sur les émotions. Exercices des prénoms ; Scoop [règle à préciser]. Objectifs : prise de contact. Objectifs de la séance : faire connaissance et installer la cohésion ; préparer le corps, mettre en énergie, amener le lâcher-prise ; écoute et observation, oser et assumer devant les autres ; exercer les émotions et les personnages muets (importance du regard) ; amener le groupe à ses premières improvisations. Points de vigilance : les prénoms doivent être acquis avant les exercices d'écoute ; repérer qui se réfugie dans le rire ou dans une seule couleur émotionnelle ; le bloc des exercices phares (45 min) sera rogné si les échauffements débordent — prévoir ce qu'on garde ; garder du temps pour le rite de fin.","duration_seconds":null,"wtype":"Accueil"}},{"id":"a470ba90-dfee-4dfb-88db-5089598cc7b8","type":"warmup","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"warmup":{"name":"Échauffement physique","desc":"Bouger et mobiliser le corps ; claques ; 1, 2, 3 bouffons [règle à préciser]. Objectifs : préparer le corps, mise en énergie, lâcher-prise.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"079496b5-7f90-4dea-b449-31f6a7c81e1d","type":"warmup","status":"planned","durationSec":1500,"locks":{},"recordedFiles":[],"warmup":{"name":"Échauffement psychophysique","desc":"Deux temps de 10 à 15 min : aimant / expulsion ; yeux fermés — mains, puis à délier ; Tadaam [règle à préciser] ; marcher : qui est où ? ; marche en émotions ; marche : qui a quelle émotion ? Objectifs : cohésion de groupe, oser et assumer, écoute et observation, premières émotions.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"bb1c44a3-5732-4fc2-b7c6-5f3e8200c053","type":"exercise","status":"planned","durationSec":1200,"locks":{},"recordedFiles":[],"exercise":{"name":"Rondes des émotions et salle d'attente silencieuse","desc":"Rondes des émotions : la même émotion grandit ou diminue en circulant ; on réagit à l'émotion par la même ou par une autre. Puis la salle d'attente silencieuse. Objectifs : exercer les émotions, travailler les personnages muets et l'importance du regard. Vigilance : la salle d'attente est le premier vrai passage devant le groupe — le silence doit tenir, personne ne se sauve par la parole."}},{"id":"1d46676d-d790-430b-a5f6-652190735d93","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Phrases imposées","desc":"Improvisations à partir de deux phrases imposées : « On m'a dit que tu voulais me parler » / « Je suis venu te dire que tu ne me verras plus, plus jamais ». Objectifs : début d'improvisation."}},{"id":"9360b26b-4c01-4982-90b4-cb07ffdeeedb","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Goal keeper","desc":"Goal keeper. Objectifs : début d'improvisation."}},{"id":"fc80db7f-d83b-4815-99be-4b2ccff3d350","type":"exercise","status":"planned","durationSec":1200,"locks":{},"recordedFiles":[],"exercise":{"name":"Début d'impro — émotions et personnages","desc":"Premières improvisations avec émotion et/ou personnages. Objectifs : début d'improvisation, réinvestir les émotions travaillées."}},{"id":"d62a11c0-81a4-469b-97d4-ba5f55f07bf2","type":"exercise","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"exercise":{"name":"Rite de fin","desc":"Tour de parole et débriefing. Objectifs : clore la séance, recueillir les ressentis, installer le rituel de fin — sur une première séance, c'est lui qui donne envie de revenir."}}],"cursor":0,"journal":[],"matchDate":""}$json$::jsonb),
      -- 10. Coaching Juniors - Seance 2 - Les emotions, developpement (9 blocs) — source : Coaching Juniors - Seance 2 - Les emotions, developpement.docx
      ('Coaching Juniors - Séance 2 - Les émotions, développement', $json${"id":"65bbc8e9-1ee9-4aa8-8046-135b9567eebd","kind":"training","title":"Coaching Juniors - Séance 2 - Les émotions, développement","locale":"fr","level":"debutant","createdAt":1793373362958,"updatedAt":1793373362958,"scoring":false,"showScores":false,"filming":false,"display":{"cointoss":"ask"},"teams":[],"meta":{"nbWarmups":3,"nbExercises":6},"targetSec":7200,"participants":[],"setlist":[{"id":"4dd946db-ecb2-45e5-992a-310a35a3642e","type":"warmup","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"warmup":{"name":"Introduction — prénoms et conscience du corps","desc":"Cadre : date à compléter · 19h00–21h00 (2h00) · Team Juniors [nom à compléter] · Encadrement : Naya [à confirmer] · groupe, lieu et niveau à compléter · Matériel : musique (Zazie) et enceinte, une chaise, papiers d'émotions à piocher. Thème : découverte du groupe et développement du travail sur les émotions. 19h00 rappel des prénoms ; 19h10 prise de conscience de son corps : relaxation, évacuation des tensions. Objectifs : retrouver le groupe, poser le corps et laisser la journée à la porte avant d'entrer dans l'émotion. Objectifs de la séance : consolider la connaissance du groupe ; expérimenter le plus d'émotions possible, imposées puis choisies ; travailler l'enchaînement écoute — émotion — réaction — attention ; installer la notion de « charger » un partenaire pour démarrer une impro. Points de vigilance : séance minutée de bout en bout, prévoir une montre et accepter de couper court ; préparer la musique et les papiers d'émotions avant l'arrivée du groupe ; repérer les émotions que chacun évite quand il a le choix.","duration_seconds":null,"wtype":"Accueil"}},{"id":"2a5f3583-1bee-4cd8-bb95-5c694ca4a3c8","type":"warmup","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"warmup":{"name":"Échauffement physique en musique","desc":"19h15 en musique (Zazie) ; 19h20 claque, avec variantes ; 19h25 ronde des émotions. Objectifs : mise en énergie par la musique, puis bascule progressive vers l'émotion dès l'échauffement.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"972e1d59-3427-454d-a6e6-88b02b7eebc9","type":"warmup","status":"planned","durationSec":1800,"locks":{},"recordedFiles":[],"warmup":{"name":"Échauffement psychophysique","desc":"19h30 voyage sanglier [règle à préciser] ; 19h40 le petit chat est mort, avec pioche d'émotion ; 19h50, si le groupe n'est pas trop nombreux, par deux, phrases à s'échanger : « T'es tellement toi, toi » / « Toi, tu es tellement toi » — « Tu es encore là » / « Oui, j'ai changé d'avis » — « Tu t'es trompé » / « Tu crois vraiment ? » — « On y est » / « Comme toujours » — « On est tous seuls » / « Abandonnés de tous » — « C'est la troisième fois » / « À deux jours d'intervalle ». Objectifs : expérimenter les émotions intérieures, puis un maximum d'émotions imposées, puis venues de soi — de l'extérieur vers l'intérieur. Vigilance : l'exercice par deux est conditionnel, décider avant la séance.","duration_seconds":null,"wtype":"Échauffement"}},{"id":"f46d1077-6518-44de-bf92-492c358c2ce3","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Ronde / goal keeper muet en émotion","desc":"Avec une émotion claire, on fait le tour du cercle et on réagit avec la même émotion, par le regard et le ressenti. Objectifs : écoute et émotion."}},{"id":"d65efaaf-cd71-4e7e-9dca-837ec74fd5ac","type":"exercise","status":"planned","durationSec":300,"locks":{},"recordedFiles":[],"exercise":{"name":"La chaise et l'élu","desc":"Une chaise au centre ; tout le monde marche avec une émotion. À un moment, l'un monte sur la chaise : tout le monde s'arrête et fige une émotion claire. Celui qui est monté dit « je suis l'élu », et les autres réagissent en grommelot, chacun avec son émotion. Objectifs : écoute — émotion — réaction — attention ; le grommelot permet de réagir fort sans avoir à trouver quoi dire."}},{"id":"11abb274-839f-407d-8a2d-4518a508f9a9","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Marche en émotion — stop, deux impros","desc":"Marche dans l'espace avec une émotion. Stop : le coach désigne deux improvisateurs qui commencent. Objectifs : porter les acquis en début d'improvisation, du plus cadré au plus libre."}},{"id":"e78fbb51-58ba-4238-8e67-9bcabd21ca4a","type":"exercise","status":"planned","durationSec":900,"locks":{},"recordedFiles":[],"exercise":{"name":"Charger un partenaire — B part","desc":"A est assis sur une chaise avec une émotion. B vient le charger, puis part ; A reste seul et peut réagir. À expliquer avant : ce que veut dire « charger » quelqu'un. Vigilance : laisser le silence s'installer quand A reste seul, c'est là que se joue la réaction."}},{"id":"c748fe42-258b-4073-b184-cc02559f7b83","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Charger un partenaire — B reste","desc":"Idem, mais B reste : l'impro démarre. Objectifs : démarrer une improvisation à partir d'un partenaire chargé."}},{"id":"2748914a-cc84-4b59-931b-a08918886d56","type":"exercise","status":"planned","durationSec":600,"locks":{},"recordedFiles":[],"exercise":{"name":"Rite de fin — cathédrale et débriefing","desc":"20h50 cathédrale ; 20h55 débriefing. Objectifs : refermer la séance par un temps collectif puis par la parole."}}],"cursor":0,"journal":[],"matchDate":""}$json$::jsonb)
    ) as x(title, data)
   where not exists (select 1 from public.shared_resources r
                      where r.owner_id = v_owner and r.resource_type = 'entrainement' and r.title = x.title);
  get diagnostics v_ajouts = row_count;
  raise notice '% coaching(s) ajoute(s) au compte', v_ajouts;
end $seed$;

-- Verification : les 15 coachings du Drive (5 deja importes + 10 nouveaux).
select t.ordre, t.titre,
       case when r.id is null then 'ABSENT' else 'present' end as etat,
       jsonb_array_length(r.data->'setlist') as blocs,
       nullif(r.data->>'matchDate', '') as date
  from (values
    (1, 'Coaching S1 du 07/09/2026 - Laugh - Première approche de l''improvisation'),
    (2, 'Coaching S2 du 14/09/2026 - Laugh - Quel improvisateur êtes-vous ?'),
    (3, 'Coaching S1 du 02/09/2026 - Les QI cuits - Inspiration musicale / Personnage / Lien / Lieu'),
    (4, 'Coaching S2 du 09/09/2026 - Les QI cuits - Confiance en l''autre / Contact / Ecoute'),
    (5, 'Coaching S3 du 16/09/2026 - Les QI cuits - Apporter plus qu''un bonjour'),
    (6, 'Coaching S3 du 21/09/2026 - Laugh - Les bases de l''improvisation'),
    (7, 'Coaching S4 du 28/09/2026 - Laugh - Amener plus qu''un bonjour'),
    (8, 'Coaching du 05/10/2026 - Laugh - Panique à bord'),
    (9, 'Coaching S4 du 23/09/2026 - Les QI cuits - Manipulation / lieu / personnage'),
    (10, 'Coaching S5 du 30/09/2026 - Les QI cuits - Manipulation lieu personnage approfondissement'),
    (11, 'Coaching S7 du 14/10/2026 - Les QI cuits - Les effets speciaux (suite)'),
    (12, 'Coaching CM2 - Séance 1 - Découverte de l''improvisation'),
    (13, 'Coaching - Nouveau groupe - Faire comprendre sans parler'),
    (14, 'Coaching Juniors - Séance 1 - Découverte du groupe et premières émotions'),
    (15, 'Coaching Juniors - Séance 2 - Les émotions, développement')
  ) as t(ordre, titre)
  left join public.shared_resources r
    on r.resource_type = 'entrainement' and r.title = t.titre
 order by t.ordre;
